struct Node;

/// Truncate to at most `max` Unicode scalar values, matching Python `len`
/// semantics on the `overview` field so the `ensures len(overview) <= 600`
/// holds for every output.
fn clamp_chars(s: &str, max: usize) -> String {
    if s.chars().count() <= max {
        s.to_string()
    } else {
        s.chars().take(max).collect()
    }
}

/// Minimal percent-encoding so the query value is a well-formed URL component.
fn encode_query(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    for b in s.bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                out.push(b as char)
            }
            _ => out.push_str(&format!("%{:02X}", b)),
        }
    }
    out
}

impl Guest for Node {
    fn run(selected: Selection, info: RunInfo) -> Digest {
        // Platform-approved enrichment fetch. The result does not influence the
        // output; `fetch` returns transport failures as values so one bad fetch
        // does not fail the node. A query text is derived from the input.
        let query_text = if let Some(first) = selected.entries.first() {
            first.title.as_str()
        } else {
            info.date.as_str()
        };
        let url = format!(
            "https://metadata.internal.example/enrich?q={}",
            encode_query(query_text)
        );
        let _ = crate::aap::caps::http_client::fetch(&url);

        // Build the material for the model from the kept items.
        let prompt = selected
            .entries
            .iter()
            .map(|e| format!("- {} ({})", e.title, e.summary))
            .collect::<Vec<_>>()
            .join("\n");

        let raw_overview = crate::aap::caps::inference_llm::infer(
            "Write a single concise overview paragraph summarising today's digest items.",
            &prompt,
            "digest",
        );

        // ensures len(overview) <= 600
        let overview = clamp_chars(&raw_overview, 600);

        Digest {
            // ensures len(date) == 10, carried from the input where
            // requires len(in1.date) == 10 already holds.
            date: info.date,
            overview,
            entries: selected.entries,
            considered: selected.considered,
        }
    }
}

export!(Node);
